cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — 400,000+ UI/UX Screenshots for Designers</title>
  <meta name="description" content="Search 615,900+ screens, 329,200+ flows, and 1,150 apps. Discover patterns, copy to Figma, and speed up design decisions." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f8fafc;
      --surface: #ffffff;
      --surface-muted: #f1f5f9;
      --text: #0f172a;
      --text-soft: #475569;
      --border: #e2e8f0;
      --accent: #4f46e5;
      --accent-2: #6366f1;
      --shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
      --radius: 18px;
      --radius-sm: 12px;
      --max: 1180px;
      --ease: cubic-bezier(0.22, 1, 0.36, 1);
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; font-family: Inter, system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); }
    a { color: inherit; text-decoration: none; }

    .container { width: min(var(--max), calc(100% - 2.5rem)); margin: 0 auto; }
    .section { padding: 82px 0; }
    .eyebrow { display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: 999px; background: #eef2ff; color: #3730a3; font-size: 13px; font-weight: 600; }
    h1, h2, h3, p { margin: 0; }
    h1 { font-size: clamp(2.1rem, 5vw, 4rem); line-height: 1.04; letter-spacing: -0.03em; }
    h2 { font-size: clamp(1.6rem, 3.4vw, 2.6rem); line-height: 1.12; letter-spacing: -0.02em; }
    .sub { margin-top: 18px; font-size: clamp(1rem, 1.7vw, 1.22rem); line-height: 1.6; color: var(--text-soft); max-width: 710px; }

    .announcement {
      position: sticky; top: 0; z-index: 50;
      background: linear-gradient(90deg, #312e81, #4338ca, #312e81);
      color: #eef2ff; font-size: 14px; text-align: center; padding: 10px 16px;
      border-bottom: 1px solid rgba(255,255,255,0.15);
    }
    .announcement strong { color: #fff; }

    .hero-wrap {
      margin-top: 22px;
      border: 1px solid var(--border);
      border-radius: calc(var(--radius) + 6px);
      background: var(--surface);
      box-shadow: var(--shadow);
      overflow: hidden;
    }
    .header {
      display: flex; align-items: center; justify-content: space-between;
      padding: 18px 24px; border-bottom: 1px solid var(--border);
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(6px);
    }
    .brand { display: flex; align-items: center; gap: 10px; font-weight: 700; }
    .logo {
      width: 34px; height: 34px; border-radius: 10px;
      background: radial-gradient(circle at 25% 25%, #8b5cf6, #4f46e5 60%, #312e81);
      display: grid; place-items: center; color: #fff; font-size: 13px; font-weight: 800;
    }
    .nav { display: flex; gap: 24px; color: var(--text-soft); font-weight: 500; font-size: 15px; }
    .nav a:hover { color: var(--text); }

    .hero {
      padding: 72px 24px 46px;
      text-align: center;
      background: radial-gradient(circle at 50% -20%, #e0e7ff 0, transparent 45%), var(--surface);
    }
    .hero-actions { margin-top: 30px; display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
    .btn {
      display: inline-flex; align-items: center; justify-content: center;
      border-radius: 999px; border: 1px solid transparent;
      padding: 12px 20px; font-weight: 600; font-size: 15px;
      transition: all .25s var(--ease);
      cursor: pointer;
    }
    .btn-primary { background: var(--accent); color: #fff; box-shadow: 0 8px 20px rgba(79,70,229,0.3); }
    .btn-primary:hover { transform: translateY(-2px); background: var(--accent-2); }
    .btn-ghost { background: #fff; color: var(--text); border-color: var(--border); }
    .btn-ghost:hover { border-color: #cbd5e1; background: #f8fafc; }

    .trusted { padding-top: 28px; }
    .trusted p { text-align: center; color: var(--text-soft); font-weight: 500; margin-bottom: 18px; }
    .logo-row { overflow: hidden; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); background: #fff; }
    .logo-track {
      display: flex; gap: 36px; width: max-content; align-items: center;
      padding: 14px 0; animation: marquee 34s linear infinite;
    }
    .logo-pill {
      padding: 9px 16px; border-radius: 999px;
      border: 1px solid var(--border); background: #f8fafc;
      color: #334155; font-size: 13px; font-weight: 600;
      white-space: nowrap;
    }

    .stats-grid {
      margin-top: 30px;
      display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px;
    }
    .stat-card {
      background: #fff; border: 1px solid var(--border); border-radius: var(--radius);
      padding: 28px; box-shadow: var(--shadow);
    }
    .stat-num {
      font-size: clamp(2rem, 4.5vw, 3.2rem); font-weight: 800; letter-spacing: -0.03em;
    }
    .stat-label { margin-top: 8px; color: var(--text-soft); font-weight: 500; }

    .feature-shell {
      margin-top: 26px; background: #fff; border: 1px solid var(--border);
      border-radius: var(--radius); box-shadow: var(--shadow); overflow: hidden;
    }
    .tabs { display: flex; flex-wrap: wrap; gap: 8px; padding: 16px; border-bottom: 1px solid var(--border); background: #f8fafc; }
    .tab {
      padding: 9px 14px; border-radius: 999px; border: 1px solid var(--border);
      background: #fff; color: #334155; font-weight: 600; font-size: 14px;
      cursor: pointer; transition: .25s var(--ease);
    }
    .tab.active { background: #eef2ff; color: #3730a3; border-color: #c7d2fe; }

    .filters { display: flex; flex-wrap: wrap; gap: 10px; padding: 16px; border-bottom: 1px solid var(--border); }
    .pill {
      padding: 8px 12px; border-radius: 999px; border: 1px solid var(--border);
      background: #fff; color: #475569; font-size: 13px; font-weight: 600;
      cursor: pointer; transition: all .2s var(--ease);
    }
    .pill.active { background: #4f46e5; color: #fff; border-color: transparent; }

    .results { padding: 16px; }
    .results-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
    .shot {
      background: linear-gradient(145deg, #e2e8f0, #f8fafc);
      border: 1px solid var(--border); border-radius: var(--radius-sm);
      aspect-ratio: 9/16; padding: 10px;
      display: flex; flex-direction: column; justify-content: space-between;
      transition: transform .25s var(--ease), box-shadow .25s var(--ease), border-color .25s var(--ease);
    }
    .shot:hover { transform: translateY(-3px); border-color: #c7d2fe; box-shadow: 0 10px 18px rgba(79,70,229,0.14); }
    .shot-top { display: flex; justify-content: space-between; align-items: center; }
    .badge { font-size: 11px; font-weight: 700; color: #4338ca; background: #eef2ff; border-radius: 999px; padding: 5px 8px; }
    .lines { display: grid; gap: 5px; }
    .line { height: 7px; border-radius: 999px; background: rgba(15,23,42,0.12); }

    .flow-toggle { display: inline-flex; gap: 8px; margin-top: 18px; background: #fff; border: 1px solid var(--border); border-radius: 999px; padding: 6px; }
    .mode-btn {
      border: 0; background: transparent; border-radius: 999px; padding: 9px 14px;
      font-weight: 600; color: #475569; cursor: pointer; transition: .25s var(--ease);
    }
    .mode-btn.active { background: #eef2ff; color: #3730a3; }

    .flow-panel {
      margin-top: 18px; border: 1px solid var(--border); border-radius: var(--radius);
      background: #fff; box-shadow: var(--shadow); overflow: hidden;
    }
    .flow-content { display: none; padding: 18px; }
    .flow-content.active { display: block; animation: fade .3s var(--ease); }
    .flow-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 12px; }
    .step {
      border: 1px solid var(--border); border-radius: var(--radius-sm);
      background: #f8fafc; padding: 12px;
    }
    .step strong { display: inline-block; margin-bottom: 8px; }

    .tools-grid { margin-top: 24px; display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 14px; }
    .tool-card { border: 1px solid var(--border); border-radius: var(--radius); background: #fff; box-shadow: var(--shadow); padding: 24px; }
    .icon {
      width: 36px; height: 36px; border-radius: 10px; background: #eef2ff;
      display: grid; place-items: center; color: #3730a3; font-weight: 800; margin-bottom: 12px;
    }
    .tool-card p { margin-top: 8px; color: var(--text-soft); line-height: 1.6; }

    .testimonials-wrap { margin-top: 28px; display: grid; gap: 14px; overflow: hidden; }
    .row-track { display: flex; gap: 14px; width: max-content; }
    .row-a { animation: marquee 34s linear infinite; }
    .row-b { animation: marquee-reverse 38s linear infinite; }
    .quote {
      width: min(360px, 85vw);
      border: 1px solid var(--border); border-radius: var(--radius-sm); background: #fff;
      padding: 18px; box-shadow: var(--shadow);
    }
    .quote p { color: #1e293b; line-height: 1.6; font-size: 14px; }
    .meta { margin-top: 12px; font-size: 13px; color: #64748b; font-weight: 600; }

    .cta-box {
      border: 1px solid var(--border); border-radius: calc(var(--radius) + 4px);
      padding: 38px 24px; background: linear-gradient(160deg, #fff, #eef2ff);
      box-shadow: var(--shadow);
      text-align: center;
    }
    .marquee-stack { margin-top: 22px; display: grid; gap: 12px; overflow: hidden; }
    .apps-track { display: flex; gap: 10px; width: max-content; }
    .apps-track.one { animation: marquee 22s linear infinite; }
    .apps-track.two { animation: marquee-reverse 24s linear infinite; }
    .app-chip {
      width: 42px; height: 42px; border-radius: 12px; border: 1px solid #cbd5e1;
      background: #fff; display: grid; place-items: center; font-size: 18px;
    }

    footer { padding: 30px 0 42px; color: #64748b; font-size: 14px; }
    .foot { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; border-top: 1px solid var(--border); padding-top: 20px; }

    @keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
    @keyframes marquee-reverse { from { transform: translateX(-50%); } to { transform: translateX(0); } }
    @keyframes fade { from { opacity: .0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

    @media (max-width: 1000px) {
      .results-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
      .flow-grid, .tools-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }
    @media (max-width: 760px) {
      .container { width: min(var(--max), calc(100% - 1.2rem)); }
      .header { padding: 14px 14px; }
      .nav { gap: 12px; font-size: 14px; }
      .hero { padding: 50px 14px 34px; }
      .stats-grid { grid-template-columns: 1fr; }
      .results-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .flow-grid, .tools-grid { grid-template-columns: 1fr; }
      .section { padding: 64px 0; }
    }
  </style>
</head>
<body>
  <div class="announcement">🎉 <strong>New:</strong> ScreenVault now indexes 615,900+ production UI screens with smart text search.</div>

  <main>
    <section class="container">
      <div class="hero-wrap">
        <header class="header">
          <div class="brand">
            <div class="logo">SV</div>
            <span>ScreenVault</span>
          </div>
          <nav class="nav" aria-label="Primary">
            <a href="index.html">Pricing</a>
            <a href="index.html">Awards</a>
            <a href="index.html">Log in</a>
          </nav>
        </header>

        <div class="hero" id="hero">
          <span class="eyebrow">400,000+ screenshots. Built for product teams.</span>
          <h1>Search proven UI patterns in seconds.</h1>
          <p class="sub">ScreenVault is the fastest way to find real product screens, UI elements, and end‑to‑end flows so you can move from blank canvas to polished concepts without guesswork.</p>
          <div class="hero-actions">
            <a href="index.html" class="btn btn-primary">Join for free</a>
            <a href="index.html" class="btn btn-ghost">See our plans</a>
          </div>
        </div>
      </div>
    </section>

    <section class="trusted container section" id="trusted-by">
      <p>Trusted by designers at high-growth startups and global product teams.</p>
      <div class="logo-row" aria-hidden="true">
        <div class="logo-track" id="trustedTrack"></div>
      </div>
    </section>

    <section class="container section" id="stats">
      <span class="eyebrow">Library Scale</span>
      <h2>The largest searchable design reference library.</h2>
      <p class="sub">Browse fresh screenshots, dissect complete user journeys, and compare patterns across categories in one organized workspace.</p>
      <div class="stats-grid">
        <article class="stat-card">
          <div class="stat-num" data-target="1150">0</div>
          <p class="stat-label">Apps indexed</p>
        </article>
        <article class="stat-card">
          <div class="stat-num" data-target="615900">0</div>
          <p class="stat-label">Screens captured</p>
        </article>
        <article class="stat-card">
          <div class="stat-num" data-target="329200">0</div>
          <p class="stat-label">Flows mapped</p>
        </article>
      </div>
    </section>

    <section class="container section" id="features-search">
      <span class="eyebrow">Powerful Search</span>
      <h2>Find screenshots by intent, element, flow, or in-screen text.</h2>
      <p class="sub">Switch perspectives instantly: explore full screens, isolate UI components, inspect complete journeys, or query text directly from real product interfaces.</p>

      <div class="feature-shell">
        <div class="tabs" id="tabGroup"></div>
        <div class="filters" id="filterGroup"></div>
        <div class="results">
          <div class="results-grid" id="resultsGrid"></div>
        </div>
      </div>
    </section>

    <section class="container section" id="features-flows">
      <span class="eyebrow">Flows & Motion</span>
      <h2>Compare complete product journeys, not just isolated screens.</h2>
      <p class="sub">Toggle between video-style overviews and prototype-style steps to understand transitions, ordering, and decision points in real apps.</p>
      <div class="flow-toggle" role="tablist" aria-label="Flow mode">
        <button class="mode-btn active" data-mode="video">Videos</button>
        <button class="mode-btn" data-mode="prototype">Prototype</button>
      </div>
      <div class="flow-panel">
        <div class="flow-content active" data-content="video">
          <div class="flow-grid">
            <div class="step"><strong>Onboarding Walkthrough</strong><p class="sub" style="font-size:14px;margin-top:0;">Observe pacing, hint density, and progressive disclosure across first-use experiences.</p></div>
            <div class="step"><strong>Checkout Completion</strong><p class="sub" style="font-size:14px;margin-top:0;">Analyze friction points between cart, shipping, payment, and success confirmation.</p></div>
            <div class="step"><strong>Subscription Upgrade</strong><p class="sub" style="font-size:14px;margin-top:0;">See how teams sequence pricing value, trial states, and upgrade confirmations.</p></div>
          </div>
        </div>
        <div class="flow-content" data-content="prototype">
          <div class="flow-grid">
            <div class="step"><strong>Step 1 — Entry</strong><p class="sub" style="font-size:14px;margin-top:0;">Trigger from Home or Settings; evaluate entry-point discoverability.</p></div>
            <div class="step"><strong>Step 2 — Decision</strong><p class="sub" style="font-size:14px;margin-top:0;">Compare option hierarchy, defaults, and confirmation patterns.</p></div>
            <div class="step"><strong>Step 3 — Completion</strong><p class="sub" style="font-size:14px;margin-top:0;">Validate success messaging, fallback states, and next-best actions.</p></div>
          </div>
        </div>
      </div>
    </section>

    <section class="container section" id="features-tools">
      <span class="eyebrow">From Inspiration to Output</span>
      <h2>Move from references to execution without context switching.</h2>
      <div class="tools-grid">
        <article class="tool-card">
          <div class="icon">F</div>
          <h3>Copy to Figma</h3>
          <p>Bring visual references into your design workspace in one click to accelerate ideation and critique rounds.</p>
        </article>
        <article class="tool-card">
          <div class="icon">S</div>
          <h3>Save to collections</h3>
          <p>Organize findings by project, team, or pattern theme so references stay searchable when you need them later.</p>
        </article>
        <article class="tool-card">
          <div class="icon">C</div>
          <h3>Leave comments</h3>
          <p>Annotate examples with rationale and decisions, turning inspiration into shared design knowledge.</p>
        </article>
      </div>
    </section>

    <section class="container section" id="testimonials">
      <span class="eyebrow">Loved by Designers</span>
      <h2>Social proof from teams shipping category-defining products.</h2>
      <div class="testimonials-wrap" aria-hidden="true">
        <div class="row-track row-a" id="quotesRowA"></div>
        <div class="row-track row-b" id="quotesRowB"></div>
      </div>
    </section>

    <section class="container section" id="cta">
      <div class="cta-box">
        <span class="eyebrow">Start Free Today</span>
        <h2 style="margin-top:14px;">Design faster with references your whole team trusts.</h2>
        <p class="sub" style="margin-left:auto;margin-right:auto;">Join thousands of product designers using ScreenVault daily to benchmark interfaces, audit competitors, and ship with confidence.</p>
        <div class="hero-actions" style="margin-top:24px;">
          <a href="index.html" class="btn btn-primary">Join for free</a>
          <a href="index.html" class="btn btn-ghost">See our plans</a>
        </div>
        <div class="marquee-stack">
          <div class="apps-track one" id="appsOne"></div>
          <div class="apps-track two" id="appsTwo"></div>
        </div>
      </div>
    </section>
  </main>

  <footer class="container">
    <div class="foot">
      <span>© 2026 ScreenVault</span>
      <span>Built for modern product design teams.</span>
    </div>
  </footer>

  <script>
    const tabs = ['Screens', 'UI Elements', 'Flows', 'Text in Screenshot'];
    const filters = ['Profile', 'Wallet', 'Welcome', 'Account Setup', 'Home', 'Subscription & Paywall', 'Login', 'Settings', 'Checkout', 'Collections'];

    const shotsByTab = {
      'Screens': ['Product Overview', 'Profile Setup', 'Revenue Dashboard', 'Team Invite', 'Plan Selection', 'Checkout Form', 'Settings Hub', 'Notification Center'],
      'UI Elements': ['Progress Slider', 'Card Variants', 'Pricing Toggle', 'Segmented Control', 'Bottom Sheet', 'Date Picker', 'Search Field', 'Tab Switcher'],
      'Flows': ['Onboarding Flow', 'Authentication Flow', 'Upgrade Flow', 'Checkout Flow', 'Refund Flow', 'Profile Edit Flow', 'Verification Flow', 'Invite Teammate Flow'],
      'Text in Screenshot': ['“Start free trial”', '“Verify your email”', '“Add payment method”', '“Continue as guest”', '“Manage subscriptions”', '“Payment successful”', '“Skip for now”', '“Try Pro for 14 days”']
    };

    const quoteData = [
      { name: 'Sebastian Speier', role: 'Product Designer', quote: 'ScreenVault became our default benchmark source before every major UI decision.' },
      { name: 'Meng To', role: 'Founder & Designer', quote: 'The quality and volume are wild. It saves hours every sprint.' },
      { name: 'Marco Cornacchia', role: 'Lead Product Designer', quote: 'We use collections for every initiative—research quality went way up.' },
      { name: 'Daryl Ginn', role: 'Design Leader', quote: 'Search is insanely fast, and the flow context beats static galleries.' },
      { name: 'Rachel How', role: 'Senior Designer', quote: 'Copy to Figma closes the gap between inspiration and production.' },
      { name: 'Haerin Song', role: 'Product Designer', quote: 'Best source I’ve found for real app patterns, especially onboarding.' }
    ];

    const trustedBrands = ['Notion', 'Linear', 'Figma', 'Shopify', 'Airbnb', 'Stripe', 'Canva', 'Duolingo', 'Slack', 'Asana'];
    const appIcons = ['🛍️','🎧','🏦','📈','🧠','🎬','🧾','🎯','🧪','🚀','🍔','🧳','📱','🧩','⚡'];

    let activeTab = tabs[0];
    let activeFilter = filters[0];

    const tabGroup = document.getElementById('tabGroup');
    const filterGroup = document.getElementById('filterGroup');
    const resultsGrid = document.getElementById('resultsGrid');

    function renderTabs() {
      tabGroup.innerHTML = '';
      tabs.forEach(tab => {
        const button = document.createElement('button');
        button.className = `tab ${tab === activeTab ? 'active' : ''}`;
        button.textContent = tab;
        button.addEventListener('click', () => {
          activeTab = tab;
          renderTabs();
          renderResults();
        });
        tabGroup.appendChild(button);
      });
    }

    function renderFilters() {
      filterGroup.innerHTML = '';
      filters.forEach(filter => {
        const button = document.createElement('button');
        button.className = `pill ${filter === activeFilter ? 'active' : ''}`;
        button.textContent = filter;
        button.addEventListener('click', () => {
          activeFilter = filter;
          renderFilters();
          renderResults();
        });
        filterGroup.appendChild(button);
      });
    }

    function seedFromString(str) {
      return [...str].reduce((acc, c) => acc + c.charCodeAt(0), 0);
    }

    function renderResults() {
      const items = shotsByTab[activeTab] || [];
      const seeded = seedFromString(activeFilter + activeTab);
      resultsGrid.innerHTML = '';
      items.forEach((label, index) => {
        const shot = document.createElement('article');
        shot.className = 'shot';
        const lineWidthA = 40 + ((seeded + index * 17) % 45);
        const lineWidthB = 30 + ((seeded + index * 13) % 50);
        shot.innerHTML = `
          <div class="shot-top">
            <span class="badge">${activeFilter}</span>
            <span style="font-size:11px;color:#64748b;font-weight:700;">${activeTab}</span>
          </div>
          <div class="lines">
            <div class="line" style="width:${lineWidthA}%"></div>
            <div class="line" style="width:${lineWidthB}%"></div>
            <div class="line" style="width:${Math.min(92, lineWidthA + 18)}%"></div>
          </div>
          <strong style="font-size:13px; line-height:1.35; color:#1e293b;">${label}</strong>
        `;
        resultsGrid.appendChild(shot);
      });
    }

    function renderTrusted() {
      const track = document.getElementById('trustedTrack');
      const list = [...trustedBrands, ...trustedBrands];
      list.forEach(name => {
        const el = document.createElement('span');
        el.className = 'logo-pill';
        el.textContent = name;
        track.appendChild(el);
      });
    }

    function renderQuotes() {
      const rowA = document.getElementById('quotesRowA');
      const rowB = document.getElementById('quotesRowB');
      const list = [...quoteData, ...quoteData];
      list.forEach((q, idx) => {
        const card = document.createElement('article');
        card.className = 'quote';
        card.innerHTML = `<p>“${q.quote}”</p><div class="meta">${q.name} · ${q.role}</div>`;
        (idx % 2 === 0 ? rowA : rowB).appendChild(card);
      });
    }

    function renderApps() {
      const one = document.getElementById('appsOne');
      const two = document.getElementById('appsTwo');
