      const items = shotsByTab[activeTab] || [];
      const seeded = seedFromString(activeFilter + activeTab);
      resultsGrid.innerHTML = '';
      items.forEach((label, index) => {
        const shot = document.createElement('article');
        shot.className = 'shot';
        const lineWidthA = 40 + ((seeded + index * 17) % 45);
        const lineWidthB = 30 + ((seeded + index * 13) % 50);
        shot.innerHTML = `
          <div class="shot-top">
            <span class="badge">${activeFilter}</span>
            <span style="font-size:11px;color:#64748b;font-weight:700;">${activeTab}</span>
          </div>
          <div class="lines">
            <div class="line" style="width:${lineWidthA}%"></div>
            <div class="line" style="width:${lineWidthB}%"></div>
            <div class="line" style="width:${Math.min(92, lineWidthA + 18)}%"></div>
          </div>
          <strong style="font-size:13px; line-height:1.35; color:#1e293b;">${label}</strong>
        `;
        resultsGrid.appendChild(shot);
      });
    }

    function renderTrusted() {
      const track = document.getElementById('trustedTrack');
      const list = [...trustedBrands, ...trustedBrands];
      list.forEach(name => {
        const el = document.createElement('span');
        el.className = 'logo-pill';
        el.textContent = name;
        track.appendChild(el);
      });
    }

    function renderQuotes() {
      const rowA = document.getElementById('quotesRowA');
      const rowB = document.getElementById('quotesRowB');
      const list = [...quoteData, ...quoteData];
      list.forEach((q, idx) => {
        const card = document.createElement('article');
        card.className = 'quote';
        card.innerHTML = `<p>“${q.quote}”</p><div class="meta">${q.name} · ${q.role}</div>`;
        (idx % 2 === 0 ? rowA : rowB).appendChild(card);
      });
    }

    function renderApps() {
      const one = document.getElementById('appsOne');
      const two = document.getElementById('appsTwo');
      [...appIcons, ...appIcons].forEach((icon, idx) => {
        const chip = document.createElement('span');
        chip.className = 'app-chip';
        chip.textContent = icon;
        (idx % 2 === 0 ? one : two).appendChild(chip);
      });
    }

    function animateCounter(element, target, duration = 1700, delay = 0) {
      const start = 0;
      const startTime = performance.now() + delay;

      function frame(now) {
        if (now < startTime) {
          requestAnimationFrame(frame);
          return;
        }
        const progress = Math.min((now - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const value = Math.floor(start + (target - start) * eased);
        element.textContent = value.toLocaleString();
        if (progress < 1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    const statsObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const nums = entry.target.querySelectorAll('.stat-num');
          nums.forEach((num, index) => animateCounter(num, Number(num.dataset.target), 1600, index * 140));
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.35 });

    statsObserver.observe(document.getElementById('stats'));

    document.querySelectorAll('.mode-btn').forEach(button => {
      button.addEventListener('click', () => {
        document.querySelectorAll('.mode-btn').forEach(btn => btn.classList.remove('active'));
        button.classList.add('active');
        const mode = button.dataset.mode;
        document.querySelectorAll('.flow-content').forEach(panel => {
          panel.classList.toggle('active', panel.dataset.content === mode);
        });
      });
    });

    renderTabs();
    renderFilters();
    renderResults();
    renderTrusted();
    renderQuotes();
    renderApps();
  </script>
</body>
</html>
